/* /_ Core Structural Layout Rules _/ */
.masonry {
  & .grid {
    column-count: var(--init-columns, 3);
    column-gap: 1.5rem;
    padding: 1rem 0;
  }

  & .item {
    break-inside: avoid;
    margin-bottom: 1.5rem;
    display: flex;
    flex-direction: column;
    background: rgba(255, 255, 255, 0.03);
    padding: 1rem;
    box-sizing: border-box;
    transform: translate3d(0, 0, 0); /* /_ Hardware GPU Acceleration _/ */
    backface-visibility: hidden;
    transition: transform 0.3s ease;

    &:hover {
      transform: scale(1.02);
    }

    & img {
      width: 100%;
      display: block;
      cursor: pointer;
    }

    &.fade-in {
      opacity: 0;
      transform: translateY(20px);
      animation: masonryFadeIn 0.4s ease forwards;
    }
  }

  /* /_ Dynamic Sliding Category Menu Layout Rules _/ */
  & .filter.menu {
    position: relative;
    display: flex;
    gap: 0.75rem;
    margin: 1.5rem auto;
    flex-wrap: wrap;
    width: max-content;
    padding: 5px;
    border: 2px solid #5b3f86;
    border-radius: 12px;
    z-index: 1;
    & .slider {
      position: absolute;
      top: 0;
      left: 0;
      background: #5b3f86;
      border-radius: 6px;
      z-index: -1;
      pointer-events: none;
      transition: transform 0.35s cubic-bezier(0.25, 1, 0.5, 1),
                  width 0.35s cubic-bezier(0.25, 1, 0.5, 1),
                  height 0.35s cubic-bezier(0.25, 1, 0.5, 1);
    }

    & .item {
      padding: 0.5rem 1.25rem;
      background: none;
      border: none;
      color: #fff;
      cursor: pointer;
      z-index: 2;
      transition: color 0.3s ease;

      &.active {
        color: #fff;
        font-weight: 600;
        background: none; /* Handled dynamically by .slider container shifts */
      }
    }

  }

  /* /_ Utility Loaders & Scroll Indicators _/ */
  & .spinner {
    display: block;
    margin: 1.5rem auto;
    width: 40px;
    height: 40px;
    /* Mask, not an image: alpha carries the shape, the token carries the colour. */
    mask-image: var(--masonry-spinner);
    mask-repeat: no-repeat;
    mask-position: center;
    mask-size: contain;
    mask-mode: alpha;
    background-color: var(--app-primary-color);
    transition: opacity 0.2s ease, visibility 0.2s ease;
    opacity: 1;
    visibility: visible;

    &:is(.hidden) {
      opacity: 0;
      visibility: hidden;
      margin: 0 auto;
      height: 0;
    }

  }

  & .sentinel {
    width: 100%;
    pointer-events: none;
  }
}
  /* /_ Lightbox Modal Structure Rules _/ */
.gallery .modal {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(10, 10, 20, 0.95);
  display: flex;
  align-items: center;
