    color: white;
    border: none;
    border-radius: 50%;
    width: 3rem; height: 3rem;
    font-size: 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.3s ease;

    &:hover { background: rgba(255, 255, 255, 0.3); }

  }
  & .close { top: 1.5rem; right: 1.5rem; }
  & .prev { left: 1.5rem; }
  & .next { right: 1.5rem; }
}
